CREATE TABLE vz_bass_call_detail ( id BIGINT NOT NULL, acct_calls INTEGER, acct_seconds BIGINT, billing_end_date DATE, billing_start_date DATE, counter_calls INTEGER, counter_dir CHARACTER VARYING(20), counter_seconds BIGINT, counter_type CHARACTER VARYING(10), country_code CHARACTER VARYING(10), customer CHARACTER VARYING(64), end_date DATE, intlcc_info CHARACTER VARYING(100), intlcc_prefix CHARACTER VARYING(20), phone_number CHARACTER VARYING(40), provider CHARACTER VARYING(64), rate_zone CHARACTER VARYING(10), start_date DATE, ytd_calls INTEGER, ytd_seconds BIGINT, CONSTRAINT bass_call_detail_pkey PRIMARY KEY (id) );
